{
  "county_id": "HVA16",
  "actions": [
    {
      "action_id": "timed-pathways",
      "action": "Adopt national cancer-specific pathways with maximum times per step and a single fast-track referral from primary care, following the Danish and Swedish model.",
      "rationale": "The optimiser scenario for HVA16 assumes 9.4 deaths postponed per year (range 1.4-18.9) at EUR 284,211 a year, and the action stayed in 94% of sensitivity runs; the county's referral processing is 70.8% within 3 days against 76.8% nationally, and referral into specialist care is the earliest stage where the county is clearly worse than the country.",
      "owner_role": "Wellbeing services county, coordinated nationally by FICAN",
      "indicator": "Patients waiting over 6 months during the year for access to specialised health care per 10 000 inhabitants",
      "roadmap_measure": "3.1.2"
    },
    {
      "action_id": "screening-reminders",
      "action": "Send a second kit with plain-language, multilingual instructions to non-responders; measure the gain as a stepped pilot.",
      "rationale": "Colorectal screening participation in HVA16 is 75.6% against the 80% target, and the expected gain is 1.5-4.37 percentage points, closing about 69% of the gap at the central estimate.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of invited to colorectal cancer screening who attended, %",
      "roadmap_measure": "1.3.1"
    },
    {
      "action_id": "pathway-timestamps",
      "action": "Add first contact, referral, diagnosis and first treatment dates, plus entry route, to the national cancer quality register and publish county-level medians quarterly.",
      "rationale": "This is the first step for every county, and in HVA16 the time from referral to diagnosis and from diagnosis to first treatment is not published by county, so the Goal 3 indicator on treatment within target times cannot be checked from open data.",
      "owner_role": "FICAN with THL and the Finnish Cancer Registry",
      "indicator": "Share of new cancer cases with all four timestamps recorded",
      "roadmap_measure": "3.2.1"
    }
  ],
  "evidence_does_not_support": "The evidence does not support a guaranteed mortality reduction: the timed-pathways estimate is a model scenario under stated assumptions, the Danish pathway evidence is before/after without a control group with a confidence interval that includes 1, and the colorectal reminder gain is borrowed from cervical screening with no Finnish colorectal effect size."
}

